mapper.select:
SELECT ar.article_id, ar.user_id, ar.article_state, ar.article_title, ar.article_img_url, ar.article_context_url, ar.brief_introduction, ar.create_time, au.non_pass_cause FROM tb_article ar LEFT JOIN tb_audit au ON ar.article_id = au.article_id
ar.article_state = #{articleSearchDto.state}
AND ar.article_id = #{articleSearchDto.articleId}
AND ar.user_id = #{articleSearchDto.userId}
AND ar.article_title like concat(#{articleSearchDto.title},'%')
ORDER BY ar.create_time DESC
